type Flow struct { Step string; Order Order }
type stepFn func(*Flow, http.ResponseWriter, *http.Request) (string, error)
var steps = map[string]stepFn{"select": selectStep, "amount": amountStep, "confirm": confirmStep}

func (f *Flow) handle(w http.ResponseWriter, r *http.Request) {
    handler, ok := steps[f.Step]
    if !ok { http.Error(w, "invalid flow step", http.StatusBadRequest); return }
    next, err := handler(f, w, r)   // the only decision point
    if err == nil { f.Step = next }
}
